(() => {
  const CONFIG = {
    attrSection: 'data-overlap', // put on any section that should be covered
    attrAmount: 'data-overlap-amount', // optional per-section override, in vh
    defaultAmountVh: 30, // how far the section lags behind, in vh
    zIndexBase: 2, // stacking: later sections above earlier ones
    desktopQuery: '(min-width: 992px)', // desktop only, disabled on tablet and down
  };

  function initOverlapSections() {
    const mm = gsap.matchMedia();

    mm.add(CONFIG.desktopQuery, () => {
      const sections = gsap.utils.toArray(`[${CONFIG.attrSection}]`);
      if (!sections.length) return;

      sections.forEach((section, i) => {
        const amountVh =
          parseFloat(section.getAttribute(CONFIG.attrAmount)) || CONFIG.defaultAmountVh;

        // Covered section below, covering section above
        gsap.set(section, { position: 'relative', zIndex: CONFIG.zIndexBase + i });

        const next = section.nextElementSibling;
        if (next) gsap.set(next, {
          position: 'relative',
          zIndex: CONFIG.zIndexBase + i +
            1
        });

        gsap.to(section, {
          y: () => (amountVh / 100) * window.innerHeight,
          ease: 'none',
          scrollTrigger: {
            trigger: section,
            start: 'bottom bottom', // begins the moment the section starts exiting
            end: 'bottom top', // done when it would have fully left
            scrub: true,
            invalidateOnRefresh: true,
          },
        });
      });
    });
  }

  initOverlapSections();
})();


